                }
                case RecordTypeInts.ESCR:
                {
                    _ESCRLocation = (stream.Position - offset);
                    return (int)ConstructibleObject_FieldIndex.ESCR;
                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
